WITH filtered AS (SELECT *, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee FROM orders WHERE channel IS NOT DISTINCT FROM 'partner') SELECT id, status, metric_name, metric_value FROM (SELECT id, status, amount, greatest_discount_shipping_fee, discount FROM filtered) src UNPIVOT (metric_value FOR metric_name IN (amount AS AMOUNT, greatest_discount_shipping_fee AS GREATEST_DISCOUNT_SHIPPING_FEE_VAL, discount AS DISCOUNT));
